style.css:
@-moz-document domain("youtube.com") {
/* Kamehameha energy beam */
  .ytp-play-progress {
    background: linear-gradient(
      90deg,
      #287bff,
      #65eaff,
      #ffffff,
      #a855f7
    ) !important;

    box-shadow:
      0 0 8px #65eaff,
      0 0 18px #3b82f6,
      0 0 30px #a855f7 !important;
  }

  /* Ultra Instinct Goku Scrubber */
  .ytp-scrubber-button {
    background-image: url("data:image/png;base64,") !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;
    background-color: transparent !important;
    border-radius: 0 !important;
    
    /* Size & alignment */
    width: 54px !important;
    height: 40px !important;
    margin-top: -14px !important;
    margin-left: -10px !important;
    
    /* Flip to face beam + Ultra Instinct glow */
    transform: scaleX(-1) !important;
    image-rendering: pixelated !important;
    filter: drop-shadow(0 0 6px #ffffff) drop-shadow(0 0 12px #65eaff) !important;
    box-shadow: none !important;
  }

  /* Glowing timeline */
  .ytp-progress-bar-container {
    filter: drop-shadow(0 0 5px #65eaff) !important;
  }
}
